type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;

    // According to problem:
    // - Either r == a.len() (treat a as column vector)
    // - Or c == a.len() (treat a as row vector)
    if r == a.len() {
        // Column vector broadcast: each row i full of a[i]
        (0..r)
            .map(|i| vec![a[i]; c])
            .collect()
    } else {
        // Otherwise, c == a.len()
        // Row vector broadcast: each row is a.clone()
        (0..r)
            .map(|_| a.clone())
            .collect()
    }
}